const CT_L=(x1,y1,x2,y2,col=CT_MUT,w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const CT_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const CT_poly=(P,col,w=4,ex='')=>`<polyline points="${P.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const CT_arrow=(x1,y1,x2,y2,col=CT_INK,w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return CT_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const CT_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* a phasor: an arrow from (x,y) of length r (px) at angle deg (counterclockwise from the right) */
const CT_ph=(x,y,r,deg,col,w=4)=>{const a=deg*Math.PI/180;return CT_arrow(x,y,x+r*Math.cos(a),y-r*Math.sin(a),col,w)};
const CT_tip=(x,y,r,deg)=>{const a=deg*Math.PI/180;return [x+r*Math.cos(a),y-r*Math.sin(a)]};
/* an angle arc at (x,y), radius r, from angle a0 to a1 (degrees, counterclockwise positive) */
const CT_arc=(x,y,r,a0,a1,col=CT_MUT,w=2.5)=>{const p=[];for(let i=0;i<=30;i++){const a=(a0+(a1-a0)*i/30)*Math.PI/180;p.push([x+r*Math.cos(a),y-r*Math.sin(a)])}return CT_poly(p,col,w)};
/* a curve of computed points f(t), t in [t0,t1] mapped to x in [x0,x1], y = yc - k*f */
const CT_pts=(f,t0,t1,x0,x1,yc,k,n=120)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,yc-k*f(t)])}return p};
const CT_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=120)=>CT_poly(CT_pts(f,t0,t1,x0,x1,yc,k,n),col,w);
const CT_area=(f,t0,t1,x0,x1,yc,k,col,op=.3)=>{const p=CT_pts(f,t0,t1,x0,x1,yc,k,60);return `<polygon points="${x0},${yc} ${p.map(q=>q[0].toFixed(1)+','+q[1].toFixed(1)).join(' ')} ${x1},${yc}" fill="${col}" fill-opacity="${op}"/>`};
const CT_res=(x1,x2,y,col=CT_INK,w=3)=>{const m=(x1+x2)/2,a=m-42,s=84/6;let p=[[x1,y],[a,y]];for(let i=0;i<6;i++)p.push([a+s*(i+.5),y+(i%2?12:-12)]);p.push([m+42,y],[x2,y]);return CT_poly(p,col,w)};
const CT_coil=(x1,x2,y,col=CT_INK,w=3)=>{const m=(x1+x2)/2,a=m-44;let d=`M${x1} ${y}L${a} ${y}`;for(let i=0;i<4;i++)d+=`A11 11 0 0 1 ${a+22*(i+1)} ${y}`;d+=`L${x2} ${y}`;return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
const CT_PI=Math.PI, CT_SIN=t=>Math.sin(t);
/* the square wave of question three: ±1 over two periods */
const CT_sq=(x0,x1,yc,k)=>{const q=(x1-x0)/4;return CT_poly([[x0,yc],[x0,yc-k],[x0+q,yc-k],[x0+q,yc+k],[x0+2*q,yc+k],[x0+2*q,yc-k],[x0+3*q,yc-k],[x0+3*q,yc+k],[x1,yc+k],[x1,yc]],BLU,4)};
